import { markHTMLString, renderComponent, renderTemplate } from "../../runtime/server/index.js";
import { isAstroComponentFactory } from "../../runtime/server/render/astro/factory.js";
import { createSlotValueFromString } from "../../runtime/server/render/slot.js";
import { decryptString } from "../encryption.js";
import { BodySizeLimitError, readBodyWithLimit } from "../request-body.js";
import { getPattern } from "../routing/pattern.js";
export const SERVER_ISLAND_ROUTE = "/_server-islands/[name]";
export const SERVER_ISLAND_COMPONENT = "_server-islands.astro";
function getServerIslandRouteData(config) {
	const segments = [[{
		content: "_server-islands",
		dynamic: false,
		spread: false
	}], [{
		content: "name",
		dynamic: true,
		spread: false
	}]];
	const route = {
		type: "page",
		component: SERVER_ISLAND_COMPONENT,
		params: ["name"],
		segments,
		pattern: getPattern(segments, config.base, config.trailingSlash),
		prerender: false,
		isIndex: false,
		fallbackRoutes: [],
		route: SERVER_ISLAND_ROUTE,
		origin: "internal",
		distURL: []
	};
	return route;
}
export function injectServerIslandRoute(config, routeManifest) {
	routeManifest.routes.unshift(getServerIslandRouteData(config));
}
function badRequest(reason) {
	return new Response(null, {
		status: 400,
		statusText: "Bad request: " + reason
	});
}
const DEFAULT_BODY_SIZE_LIMIT = 1024 * 1024;
export async function getRequestData(request, bodySizeLimit = DEFAULT_BODY_SIZE_LIMIT) {
	switch (request.method) {
		case "GET": {
			const url = new URL(request.url);
			const params = url.searchParams;
			if (!params.has("s") || !params.has("e") || !params.has("p")) {
				return badRequest("Missing required query parameters.");
			}
			const encryptedSlots = params.get("s");
			return {
				encryptedComponentExport: params.get("e"),
				encryptedProps: params.get("p"),
				encryptedSlots
			};
		}
		case "POST": {
			try {
				const body = await readBodyWithLimit(request, bodySizeLimit);
				const raw = new TextDecoder().decode(body);
				const data = JSON.parse(raw);
				// Validate that slots is not plaintext
				if (Object.hasOwn(data, "slots") && typeof data.slots === "object") {
					return badRequest("Plaintext slots are not allowed. Slots must be encrypted.");
				}
				// Validate that componentExport is not plaintext
				if (Object.hasOwn(data, "componentExport") && typeof data.componentExport === "string") {
					return badRequest("Plaintext componentExport is not allowed. componentExport must be encrypted.");
				}
				return data;
			} catch (e) {
				if (e instanceof BodySizeLimitError) {
					return new Response(null, {
						status: 413,
						statusText: e.message
					});
				}
				if (e instanceof SyntaxError) {
					return badRequest("Request format is invalid.");
				}
				throw e;
			}
		}
		default: {
			// Method not allowed: https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/405
			return new Response(null, { status: 405 });
		}
	}
}
export function createEndpoint(manifest) {
	const page = async (result) => {
		const params = result.params;
		if (!params.name) {
			return new Response(null, {
				status: 400,
				statusText: "Bad request"
			});
		}
		const componentId = params.name;
		// Get the request data from the body or search params
		const data = await getRequestData(result.request, manifest.serverIslandBodySizeLimit);
		// probably error
		if (data instanceof Response) {
			return data;
		}
		const serverIslandMappings = await manifest.serverIslandMappings?.();
		const serverIslandMap = await serverIslandMappings?.serverIslandMap;
		let imp = serverIslandMap?.get(componentId);
		if (!imp) {
			return new Response(null, {
				status: 404,
				statusText: "Not found"
			});
		}
		const key = await manifest.key;
		// Decrypt componentExport
		let componentExport;
		try {
			componentExport = await decryptString(key, data.encryptedComponentExport, `export:${componentId}`);
		} catch (_e) {
			return badRequest("Encrypted componentExport value is invalid.");
		}
		const encryptedProps = data.encryptedProps;
		let props = {};
		if (encryptedProps !== "") {
			try {
				const propString = await decryptString(key, encryptedProps, `props:${componentId}`);
				props = JSON.parse(propString);
			} catch (_e) {
				return badRequest("Encrypted props value is invalid.");
			}
		}
		// Decrypt slots
		let decryptedSlots = {};
		const encryptedSlots = data.encryptedSlots;
		if (encryptedSlots !== "") {
			try {
				const slotsString = await decryptString(key, encryptedSlots, `slots:${componentId}`);
				decryptedSlots = JSON.parse(slotsString);
			} catch (_e) {
				return badRequest("Encrypted slots value is invalid.");
			}
		}
		const componentModule = await imp();
		let Component = componentModule[componentExport];
		const slots = {};
		for (const prop in decryptedSlots) {
			slots[prop] = createSlotValueFromString(decryptedSlots[prop]);
		}
		// Prevent server islands from being indexed
		result.response.headers.set("X-Robots-Tag", "noindex");
		// Wrap Astro components so we can set propagation to
		// `self` which is needed to force the runtime to wait
		// on the component before sending out the response headers.
		// This allows the island to set headers (cookies).
		if (isAstroComponentFactory(Component)) {
			const ServerIsland = Component;
			Component = function(...args) {
				return ServerIsland.apply(this, args);
			};
			Object.assign(Component, ServerIsland);
			Component.propagation = "self";
		}
		// Server island modules are selected at runtime, outside the static propagation graph.
		// Mark this route as propagating so async slots register head assets before streaming.
		// https://github.com/withastro/astro/issues/17870
		result._metadata.routeHasPropagation = true;
		const renderPropagatedHead = () => markHTMLString(result._metadata.extraHead.join(""));
		return renderTemplate`${renderPropagatedHead}${renderComponent(result, "Component", Component, props, slots)}`;
	};
	page.isAstroComponentFactory = true;
	const instance = {
		default: page,
		partial: true
	};
	return instance;
}
